(function(){
'use strict';
const area=document.getElementById('workspace-content'),repo=window.DaydreamRepository,esc=window.DaydreamDB.escape,get=id=>document.getElementById(id),Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;
let current=null,draft={name:'',text:''},dirty=false,revision=0,timer,speech,chain=Promise.resolve();
function status(text,error=false){const el=get('capture-save-status');if(el){el.textContent=text;el.classList.toggle('save-error',error);}}
function speechStatus(text,error=false){const el=get('speech-status');if(el){el.textContent=text;el.classList.toggle('save-error',error);}}
function stopSpeech(){speech?.abort();speech=null;}
function changed(){dirty=true;revision++;status('Unsaved changes');clearTimeout(timer);timer=setTimeout(flush,650);}
async function flush(){clearTimeout(timer);if(!dirty)return chain.then(()=>true);if(!draft.text.trim()&&!current){dirty=false;return true;}const rev=revision,copy={...draft,id:current?.id,createdAt:current?.createdAt,assignment:current?.assignment};status('Saving…');chain=chain.catch(()=>{}).then(()=>repo.saveCapture(copy));try{const saved=await chain;current=saved;if(rev===revision){dirty=false;status(repo.status?.()||'Saved on this device');}return true;}catch(err){status(`Not saved: ${err.message}. Your text is still here.`,true);return false;}}
async function render(){if(window.DaydreamAuth&&!window.DaydreamAuth.user){window.DaydreamAuth.require('#capture');return;}stopSpeech();try{await repo.open();const captures=await repo.all('captures');if(current&&!dirty){current=captures.find(c=>c.id===current.id)||null;draft=current?{name:current.name,text:current.text}:{name:'',text:''};}
area.innerHTML=`<div class="workspace-toolbar"><a href="#home" class="writer-brand" aria-label="Daydream home"><span class="brand-mark">d.</span><span class="brand-name">daydream</span></a><a href="#workspace" class="quiet-link">All your realities</a><div class="workspace-utilities"><button class="account-button" data-account-open>Account</button><button class="account-button" data-auth-logout>Log Out</button><button class="tutorial-help" data-tutorial-open aria-label="Open workspace tutorial">?</button><button class="secondary-button" data-pause>Pause and return to now</button></div></div><div class="capture-heading"><p class="eyebrow">BEFORE THE STORY HAS A SHAPE</p><h1>Catch the thought.</h1><p>Type a few words, or speak them aloud. Find a place for them later.</p></div><div class="capture-layout"><section class="capture-writing" aria-label="Capture editor"><div class="capture-editor-toolbar"><span class="node-tag">${current?'SAVED CAPTURE':'NEW CAPTURE'}</span><button class="text-button" data-capture-action="new">New capture</button></div><label for="capture-name">Name <span>(optional)</span></label><input id="capture-name" maxlength="200" value="${esc(draft.name)}" placeholder="A passing thought"><label for="capture-text">Your thought or transcript</label><textarea id="capture-text" dir="auto" placeholder="A scene, a conversation, a place…">${esc(draft.text)}</textarea><div class="speech-area">${Recognition?'<div class="speech-controls"><button class="secondary-button" id="voice-start" data-capture-action="voice">Start speech-to-text</button><button class="secondary-button" id="voice-stop" data-capture-action="stop" hidden>Stop microphone</button><label>Language<select id="speech-language"><option value="en-US">English</option><option value="ur-PK">Urdu</option></select></label></div><p class="field-help">Your browser’s speech service may process audio remotely. You choose whether to start.</p>':'<p class="speech-fallback">Speech-to-text is unavailable in this browser. Type, paste a transcript, or use your device’s keyboard dictation.</p>'}<p id="speech-status" role="status">${Recognition?'Microphone is off.':'Text capture is ready.'}</p><p id="speech-interim"></p></div><div class="capture-actions"><button class="button" data-capture-action="save">Save capture</button><button class="secondary-button" data-capture-action="assign">Place in a reality</button>${current?'<button class="delete-button" data-capture-action="delete">Delete capture</button>':''}</div><p id="capture-save-status" role="status" aria-live="polite">${dirty?'Unsaved changes':esc(repo.status?.()||'Saved on this device')}</p>${current?.assignment?`<p>A copy was placed in <a href="#world/${encodeURIComponent(current.assignment.worldId)}">your reality</a>. Editing this capture does not change that copy.</p>`:''}<p class="storage-note">${repo.isAccount?'Writing syncs with your Firebase account. Unsynced changes remain on this device.':'Writing stays in this browser on this device. Clearing site data removes it.'} Place a capture in a world to export it from its document. No audio files are stored by this site.</p></section><aside class="capture-library"><div class="panel-title"><h2>Your captures</h2><span>${captures.length}</span></div>${captures.slice().reverse().map(c=>`<button class="capture-card ${current?.id===c.id?'selected':''}" data-capture-id="${esc(c.id)}"><span>${esc(c.name)}</span><p>${esc(c.text.slice(0,125))}</p><small>${c.assignment?'Placed':'Unassigned'}</small></button>`).join('')||'<p>No captures yet. Save your first thought.</p>'}</aside></div>`;document.title='Dream Capture — Daydream';}catch(err){area.innerHTML=`<p class="storage-error" role="alert">${esc(err.message)}</p>`;}}
const consent=document.createElement('dialog');consent.setAttribute('aria-labelledby','speech-consent-title');consent.innerHTML='<h2 id="speech-consent-title">Speak your thought</h2><p>Your browser’s speech service may send microphone audio to its provider for transcription. Daydream cannot guarantee on-device processing. This site does not retain an audio recording.</p><p>Review and edit the transcript before placing it in a reality.</p><div class="dialog-actions"><button class="secondary-button" id="speech-cancel">Keep typing</button><button class="button" id="speech-allow">Start microphone</button></div>';document.body.append(consent);get('speech-cancel').onclick=()=>consent.close();get('speech-allow').onclick=()=>{consent.close();speech=new window.DaydreamSpeechInput(Recognition,{onText(text){if(location.hash!=='#capture')return;draft.text+=`${draft.text?' ':''}${text}`;get('capture-text').value=draft.text;changed();},onInterim(text){if(get('speech-interim'))get('speech-interim').textContent=text;},onStatus:speechStatus,onEnd(){flush();if(get('voice-start')){get('voice-start').hidden=false;get('voice-stop').hidden=true;get('speech-language').disabled=false;}}});try{speech.start(get('speech-language').value);get('voice-start').hidden=true;get('voice-stop').hidden=false;get('speech-language').disabled=true;}catch(err){speechStatus(err.message,true);}};
const assignment=document.createElement('dialog');assignment.className='work-dialog';document.body.append(assignment);
async function assign(){const realities=await repo.all('realities');if(!current){status('Save a thought first.',true);return;}if(current.assignment){status('This capture has already been placed.');return;}if(!realities.length){status('Create an alternative reality first.',true);return;}
assignment.innerHTML=`<form><h2>Place your capture</h2><p>A copy goes into your reality. The original stays here.</p><label>Alternative reality<select name="reality">${realities.map(r=>`<option value="${esc(r.id)}">${esc(r.name)}</option>`).join('')}</select></label><label>Destination<select name="target"></select></label><label>New document function<select name="type">${Object.entries(window.DaydreamDB.TYPES).map(([k,v])=>`<option value="${k}" ${k==='note'?'selected':''}>${esc(v)}</option>`).join('')}</select></label><p class="modal-error" role="alert"></p><div class="dialog-actions"><button type="button" class="secondary-button" data-close>Cancel</button><button class="button">Place capture</button></div></form>`;
async function targets(){const list=await repo.all('catalog',assignment.querySelector('[name=reality]').value);assignment.querySelector('[name=target]').innerHTML='<option value="">Create a new document</option>'+list.filter(d=>!d.canvasType).map(d=>`<option value="${esc(d.id)}">Append to ${esc(d.name)}</option>`).join('');}await targets();assignment.querySelector('[name=reality]').onchange=targets;assignment.querySelector('[data-close]').onclick=()=>assignment.close();assignment.querySelector('form').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target);current=await repo.assignCapture(current.id,f.get('reality'),f.get('target'),f.get('type'));assignment.close();await render();status('Capture placed. The original is kept here.');}catch(err){assignment.querySelector('.modal-error').textContent=err.message;}};assignment.showModal();}
area.addEventListener('input',e=>{if(['capture-name','capture-text'].includes(e.target.id)){draft={name:get('capture-name').value,text:get('capture-text').value};changed();}});
area.addEventListener('click',async e=>{const b=e.target.closest('[data-capture-action],[data-capture-id]');if(!b)return;try{const action=b.dataset.captureAction;if(action==='voice'){consent.showModal();return;}if(action==='stop'){speech?.stop();return;}if(speech?.active){speech.stop();status('Microphone stopping. Review the transcript, then continue.');return;}if(!await flush())return;if(b.dataset.captureId){current=await repo.get('captures',b.dataset.captureId);await render();return;}if(action==='new'){current=null;draft={name:'',text:''};await render();get('capture-text').focus();}if(action==='save'){await render();status(current?(repo.status?.()||'Saved on this device'):'Write a thought before saving.');}if(action==='assign')await assign();if(action==='delete'&&confirm('Delete this capture? Copies placed in your reality will stay.')){await repo.batch([{table:'captures',remove:current.id}]);current=null;draft={name:'',text:''};await render();}}catch(err){status(err.message,true);}});
async function beforeNavigate(){if(!await flush()) {history.replaceState(null,'','#capture');return false;}stopSpeech();return true;}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}stopSpeech();});
window.DaydreamCapture={render,beforeNavigate,hasUnsaved:()=>dirty,reset(){clearTimeout(timer);stopSpeech();consent.close();assignment.close();current=null;draft={name:'',text:''};dirty=false;revision++;chain=Promise.resolve();},prepareAction:async()=>{if(speech?.active){speech.stop();status('Review the transcript when the microphone stops.');return false;}return flush();}};
})();
